package com.forgeci.application.github;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import java.net.URI; import java.net.http.*; import java.nio.charset.StandardCharsets; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component;
@Component public class GitHubClient { private final HttpClient http=HttpClient.newHttpClient(); private final ObjectMapper mapper; private final String clientId,clientSecret,redirectUri; public GitHubClient(ObjectMapper mapper,@Value("${forgeci.github.client-id:}") String clientId,@Value("${forgeci.github.client-secret:}") String clientSecret,@Value("${forgeci.github.redirect-uri:http://localhost:8080/api/v1/connections/github/callback}") String redirectUri){this.mapper=mapper;this.clientId=clientId;this.clientSecret=clientSecret;this.redirectUri=redirectUri;} public String authorizationUrl(String state){return "https://github.com/login/oauth/authorize?client_id="+enc(clientId)+"&redirect_uri="+enc(redirectUri)+"&scope="+enc("repo read:user")+"&state="+enc(state);} public TokenExchange exchangeCode(String code) throws Exception {var body="client_id="+enc(clientId)+"&client_secret="+enc(clientSecret)+"&code="+enc(code)+"&redirect_uri="+enc(redirectUri);var req=HttpRequest.newBuilder(URI.create("https://github.com/login/oauth/access_token")).header("Accept","application/json").header("Content-Type","application/x-www-form-urlencoded").POST(HttpRequest.BodyPublishers.ofString(body)).build();var res=http.send(req,HttpResponse.BodyHandlers.ofString());if(res.statusCode()!=200)throw new IllegalStateException("GitHub OAuth exchange failed");JsonNode n=mapper.readTree(res.body());if(n.has("error"))throw new IllegalStateException("GitHub OAuth exchange failed");return new TokenExchange(n.get("access_token").asText());} public GitHubUser currentUser(String token) throws Exception {var req=HttpRequest.newBuilder(URI.create("https://api.github.com/user")).header("Authorization","Bearer "+token).header("Accept","application/vnd.github+json").header("User-Agent","ForgeCI").GET().build();var res=http.send(req,HttpResponse.BodyHandlers.ofString());if(res.statusCode()!=200)throw new IllegalStateException("GitHub credentials are invalid or revoked");var n=mapper.readTree(res.body());return new GitHubUser(n.get("id").asText(),n.get("login").asText());} public List<GitHubRepository> repositories(String token) throws Exception {var req=HttpRequest.newBuilder(URI.create("https://api.github.com/user/repos?per_page=100")).header("Authorization","Bearer "+token).header("Accept","application/vnd.github+json").header("User-Agent","ForgeCI").GET().build();var res=http.send(req,HttpResponse.BodyHandlers.ofString());if(res.statusCode()==401)throw new IllegalStateException("GitHub credentials are invalid or revoked");if(res.statusCode()!=200)throw new IllegalStateException("Unable to list GitHub repositories");var a=mapper.readTree(res.body());var out=new ArrayList<GitHubRepository>();for(var n:a)out.add(new GitHubRepository(n.get("id").asText(),n.get("name").asText(),n.get("full_name").asText(),n.get("clone_url").asText(),n.path("default_branch").asText("main"),n.path("private").asBoolean()));return out;} private String enc(String s){return java.net.URLEncoder.encode(s==null?"":s,StandardCharsets.UTF_8);} public record TokenExchange(String accessToken){} public record GitHubUser(String id,String login){} public record GitHubRepository(String id,String name,String fullName,String cloneUrl,String defaultBranch,boolean privateRepository){}
}
